package org.matlab.dsc.domain;

import java.util.UUID;

/**
 * Stable identity helpers. Fixture-derived objects use deterministic ids so a
 * replayed case pack is byte-for-byte reproducible; interactive objects use
 * random UUIDs. Identities are never regenerated by recomputation.
 */
public final class StableId {
    private StableId() {
    }

    public static String source(String sampleId, SourceKind kind, String tag) {
        return "src:" + sampleId + ":" + kind.wire() + (tag == null || tag.isEmpty() ? "" : ":" + tag);
    }

    public static String node(String... parts) {
        StringBuilder sb = new StringBuilder("node");
        for (String p : parts) {
            sb.append(':').append(p);
        }
        return sb.toString();
    }

    public static String event(long seq) {
        return "ev:" + seq;
    }

    public static String attempt(String tag) {
        return "attempt:" + tag + ":" + UUID.randomUUID();
    }

    public static String randomNode(String kind) {
        return "node:" + kind + ":" + UUID.randomUUID();
    }
}
